s=open(p).read()
def r(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
r("""	int HookSpeed = GameClient()->m_aClients[ClientId].m_Predicted.m_Tuning.m_HookFireSpeed;
	if(HookSpeed <= 0)
		return;

	int HookLength =""","""	const float HookSpeed = GameClient()->m_aClients[ClientId].m_Predicted.m_Tuning.m_HookFireSpeed;
	if(HookSpeed <= 0.0f)
		return;

	const float HookLength =""")
r("""	bool DoBreak = false;
	std::vector""","""	bool DoBreak = false;
	bool Teleported = false;
	std::vector""")
r("""		if(ClientId >= 0 && GameClient()->IntersectCharacter(OldPos, NewPos, FinishPos, ClientId) != -1)
		{""","""		// the hook can only catch a tee in front of the tile it hits, and not when it
		// enters the retracting state right after going through a teleporter
		if(ClientId >= 0 && !(DoBreak && Teleported) && GameClient()->IntersectCharacter(OldPos, FinishPos, FinishPos, ClientId) != -1)
		{""")
r("""				InitPos = NewPos = Collision()->TeleOuts(Tele - 1)[0];
			}""","""				InitPos = NewPos = Collision()->TeleOuts(Tele - 1)[0];
				Teleported = true;
			}""")
r("""		if(Hit && Hit != TILE_TELEINHOOK)
		{
			if(Hit != TILE_NOHOOK)""","""		if(Hit && Hit != TILE_TELEINHOOK)
		{
			// when the hook reaches its maximum length in this tick it starts retracting
			// and can no longer attach to the ground
			if(Hit != TILE_NOHOOK && !DoBreak)""")
r("""		const vec2 PerpToAngle = direction(pi / 2.0f - angle(Direction)) * GameClient()->m_Camera.m_Zoom;""","""		const vec2 PerpToAngle = normalize(vec2(Direction.y, -Direction.x)) * GameClient()->m_Camera.m_Zoom;""")
open(p,'w').write(s)
p='src/game/client/gameclient.cpp'
s=open(p).read()
r("CCharacterCore::PhysicalSize() / 2.0f + 2.0f","CCharacterCore::PhysicalSize() + 2.0f")
open(p,'w').write(s)
E
